class Solution:
    def evenProduct(self, nums: List[int]) -> int:
        n = len(nums)
        total = n * (n + 1) // 2
        odd = run = 0
        for x in nums:
            if x % 2:
                run += 1
            else:
                odd += run * (run + 1) // 2
                run = 0
        odd += run * (run + 1) // 2
        return total - odd

