class Solution {
public:
    long long evenProduct(vector<int>& nums) {
        long long n = nums.size();
        long long total = n * (n + 1) / 2, odd = 0, run = 0;
        for (int x : nums) {
            if (x % 2) run++;
            else { odd += run * (run + 1) / 2; run = 0; }
        }
        odd += run * (run + 1) / 2;
        return total - odd;
    }
};

